  root=document.querySelector<HTMLElement>('#ui')!;scene?:BattleScene;save=loadSave();audio=new AudioDirector();private _screen='loading';selectedLevel=0;selectedChapter='';difficulty:Difficulty='normal';modal='';wasPaused=false;lastFocus?:HTMLElement;resultShown=false;toastTimer=0;
